#include <vector>
#include <stdlib.h>

using namespace std;

class Solution {
    public:
        long long maxProfit(vector<int>& prices, vector<int>& strategy, int k) {

            vector<long long> baseSums(1, prices[0] * strategy[0]);

            vector<long long> modification(k, 1);
            for (long long x = 0; x < k / 2; x++) {
                modification[x] = 0;
            }
    

            for (long long i = 1; i < prices.size(); i++) {
                baseSums.push_back(prices[i] * strategy[i] + baseSums[i-1]); 
    
            }
            // printf("\n\nBaseSums");
            // for (int i : baseSums) {
            //     printf("%d ", i);
            // }
    
            // printf("\n %d", baseSums.back());
            long long baseTotal = baseSums.back();
            long long maxTotal = baseTotal;

            for (int i = 0; i <= baseSums.size()-k; i++) {
    
    
                long long baseProf = baseSums[i+k-1] - (i > 0 ? baseSums[i-1] : 0);
    
    
                
                vector<long long> subArray(1, prices[i] * modification[0]);
                for (int j = 1; j < k; j++) {
    
                    subArray.push_back(prices[i+j] * modification[j]+subArray[j-1]);
    
                }
                    // printf("SubArray \n");
                    // for (int x : subArray) {
                    //     printf("%lld ", x);
                    // } 
    
    
                long long delta = subArray.back() - baseProf;
    
                maxTotal = (baseTotal + delta > maxTotal) ? baseTotal + delta : maxTotal;
                subArray.clear();
            }
    
    
            
    
    
            return maxTotal;
        }
    };



